<?php
defined('ABSPATH')||exit; class CFP_Tracking{public function hooks():void{add_action('woocommerce_checkout_order_processed',array($this,'order_created'),10,3); add_action('woocommerce_order_status_completed',array($this,'order_paid'));} public function track(string $event,int $funnel=0,int $step=0,int $order=0,string $email='',float $value=0,array $meta=array()):void{global $wpdb; $wpdb->insert(CFP_Database::table('analytics'),array('funnel_id'=>$funnel?:null,'step_id'=>$step?:null,'order_id'=>$order?:null,'customer_email'=>sanitize_email($email),'event_type'=>sanitize_key($event),'value'=>$value,'meta'=>wp_json_encode($meta),'created_at'=>current_time('mysql'))); do_action('cfp_event_tracked',$event,$meta);} public function order_created(int $order_id):void{$this->track('order_created',0,0,$order_id,'',0);} public function order_paid(int $order_id):void{$order=wc_get_order($order_id); if($order){$this->track('order_paid',0,0,$order_id,$order->get_billing_email(),(float)$order->get_total());}}}
